// Keep emitted helpers byte-identical between the two translator runtimes.
import { readFileSync, writeFileSync } from 'node:fs';
import assert from 'node:assert/strict';
import { objpakRuntime } from '../js/src/formal/objpak-runtime.js';
const path = new URL('../rust/src/formal/objpak_runtime.rs', import.meta.url);
const output = [
  '//! Generated by experiments/issue-16-objc-runtime.mjs from the independently',
  '//! implemented JavaScript helper definitions; do not edit by hand.',
  ...Object.entries(objpakRuntime).map(
    ([language, source]) =>
      `pub(crate) const ${language.toUpperCase()}: &str = r##"${source}"##;`
  ),
  '',
].join('\n');
if (process.argv.includes('--check')) {
  assert.equal(readFileSync(path, 'utf8'), output);
} else {
  writeFileSync(path, output);
}
